// remaster core - manifest loader, hook registry, config, logger.
//
// Every address used by the remaster comes from a manifest generated by the
// Ghidra analysis, never from a hand-typed constant. Each entry is validated
// against the live image before any hook is installed, so a mismatched build
// degrades to "feature disabled" instead of crashing the game.

#include "remaster.h"

#include <stdio.h>
#include <string.h>

#ifndef REMASTER_NO_MINHOOK
#include "MinHook.h"
#endif

namespace remaster {

static Logger g_log;

Logger& log() {
    return g_log;
}

Config& config() {
    static Config cfg;
    return cfg;
}

Manifest& manifest() {
    static Manifest m;
    return m;
}

// ---------------------------------------------------------------- logger

void Logger::init(const char* path) {
    path_[0] = 0;
    if (path && *path) {
        strncpy(path_, path, sizeof(path_) - 1);
        path_[sizeof(path_) - 1] = 0;
    }
    FILE* f = fopen(path_, "w");
    if (f) {
        fclose(f);
    }
}

void Logger::write(const char* level, const char* fmt, ...) {
    char line[2048];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(line, sizeof(line), fmt, ap);
    va_end(ap);
    if (n < 0) {
        return;
    }
    FILE* f = fopen(path_, "a");
    if (f) {
        fprintf(f, "[%s] %s\n", level, line);
        fclose(f);
    }
    OutputDebugStringA(line);
}

// ---------------------------------------------------------------- config

bool Config::load(const char* path) {
    char section[128] = "";
    FILE* f = fopen(path, "r");
    if (!f) {
        return false;
    }
    char line[512];
    while (fgets(line, sizeof(line), f)) {
        char* s = line;
        while (*s == ' ' || *s == '\t') {
            s++;
        }
        char* nl = strpbrk(s, "\r\n");
        if (nl) {
            *nl = 0;
        }
        if (*s == 0 || *s == ';' || *s == '#') {
            continue;
        }
        if (*s == '[') {
            char* end = strchr(s, ']');
            if (end) {
                *end = 0;
                char* sec = s + 1;
                while (*sec == ' ' || *sec == '\t') {
                    sec++;
                }
                char* sec_end = sec + strlen(sec);
                while (sec_end > sec && (sec_end[-1] == ' ' || sec_end[-1] == '\t')) {
                    *--sec_end = 0;
                }
                strncpy(section, sec, sizeof(section) - 1);
                section[sizeof(section) - 1] = 0;
            }
            continue;
        }
        char* eq = strchr(s, '=');
        if (!eq) {
            continue;
        }
        *eq = 0;
        char* key = s;
        char* val = eq + 1;
        while (*val == ' ' || *val == '\t') {
            val++;
        }
        char* key_end = key + strlen(key);
        while (key_end > key && (key_end[-1] == ' ' || key_end[-1] == '\t')) {
            *--key_end = 0;
        }
        char* val_end = val + strlen(val);
        while (val_end > val && (val_end[-1] == ' ' || val_end[-1] == '\t')) {
            *--val_end = 0;
        }
        set(section, key, val);
    }
    fclose(f);
    return true;
}

void Config::set(const char* section, const char* key, const char* value) {
    char full[192];
    snprintf(full, sizeof(full), "%s.%s", section, key);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (strcmp(keys_[i], full) == 0) {
            strncpy(values_[i], value, sizeof(values_[i]) - 1);
            values_[i][sizeof(values_[i]) - 1] = 0;
            return;
        }
    }
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (keys_[i][0] == 0) {
            strncpy(keys_[i], full, sizeof(keys_[i]) - 1);
            strncpy(values_[i], value, sizeof(values_[i]) - 1);
            return;
        }
    }
}

const char* Config::get(const char* section, const char* key, const char* fallback) {
    char full[192];
    snprintf(full, sizeof(full), "%s.%s", section, key);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (keys_[i][0] && strcmp(keys_[i], full) == 0) {
            return values_[i];
        }
    }
    return fallback;
}

int Config::getInt(const char* section, const char* key, int fallback) {
    const char* v = get(section, key, 0);
    if (!v || !*v) {
        return fallback;
    }
    return (int)strtol(v, 0, 0);
}

float Config::getFloat(const char* section, const char* key, float fallback) {
    const char* v = get(section, key, 0);
    if (!v || !*v) {
        return fallback;
    }
    return (float)strtod(v, 0);
}

bool Config::getBool(const char* section, const char* key, bool fallback) {
    const char* v = get(section, key, 0);
    if (!v || !*v) {
        return fallback;
    }
    if (v[0] == '0' || v[0] == 'n' || v[0] == 'N' || v[0] == 'f' || v[0] == 'F') {
        return false;
    }
    return true;
}

// ---------------------------------------------------------------- manifest

bool Manifest::load(const char* path) {
    char* buf = 0;
    FILE* f = fopen(path, "rb");
    if (!f) {
        return false;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = (char*)malloc((size_t)size + 1);
    if (!buf) {
        fclose(f);
        return false;
    }
    size_t got = fread(buf, 1, (size_t)size, f);
    fclose(f);
    buf[got] = 0;

    // Minimal flat parser: "key = value" lines, '#' comments.
    char* p = buf;
    while (p && *p) {
        char* eol = strpbrk(p, "\r\n");
        if (eol) {
            *eol = 0;
        }
        char* s = p;
        while (*s == ' ' || *s == '\t') {
            s++;
        }
        if (*s && *s != '#') {
            char* eq = strchr(s, '=');
            if (eq) {
                *eq = 0;
                char* key = s;
                char* val = eq + 1;
                while (*val == ' ' || *val == '\t') {
                    val++;
                }
                char* ke = key + strlen(key);
                while (ke > key && (ke[-1] == ' ' || ke[-1] == '\t')) {
                    *--ke = 0;
                }
                set(key, val);
            }
        }
        p = eol ? eol + 1 : 0;
    }
    free(buf);
    loaded_ = true;
    return true;
}

void Manifest::set(const char* key, const char* value) {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (strcmp(keys_[i], key) == 0) {
            strncpy(values_[i], value, sizeof(values_[i]) - 1);
            values_[i][sizeof(values_[i]) - 1] = 0;
            return;
        }
    }
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (keys_[i][0] == 0) {
            strncpy(keys_[i], key, sizeof(keys_[i]) - 1);
            strncpy(values_[i], value, sizeof(values_[i]) - 1);
            return;
        }
    }
}

const char* Manifest::get(const char* key, const char* fallback) const {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (keys_[i][0] && strcmp(keys_[i], key) == 0) {
            return values_[i];
        }
    }
    return fallback;
}

unsigned int Manifest::getAddr(const char* key) const {
    const char* v = get(key, 0);
    if (!v || !*v) {
        return 0;
    }
    return (unsigned int)strtoul(v, 0, 0);
}

const unsigned char* Manifest::getBytes(const char* key, int* out_len) const {
    const char* v = get(key, 0);
    if (!v || !*v) {
        if (out_len) {
            *out_len = 0;
        }
        return 0;
    }
    // "AA BB CC" (spaces tolerated)
    static unsigned char buf[64];
    int n = 0;
    const char* p = v;
    while (*p && n < 64) {
        while (*p == ' ' || *p == '\t') {
            p++;
        }
        if (!*p) {
            break;
        }
        if (p[0] == '?' && p[1] == '?') {
            buf[n++] = 0xFF;
            p += 2;
            continue;
        }
        char hex[3] = { p[0], p[1], 0 };
        if (!hex[0] || !hex[1]) {
            break;
        }
        buf[n++] = (unsigned char)strtoul(hex, 0, 16);
        p += 2;
    }
    if (out_len) {
        *out_len = n;
    }
    return buf;
}

bool Manifest::getPattern(const char* key, unsigned char* out_bytes, unsigned char* out_mask, int* out_len, int max_len) const {
    const char* v = get(key, 0);
    if (!v || !*v || !out_bytes || !out_mask || max_len <= 0) {
        if (out_len) {
            *out_len = 0;
        }
        return false;
    }
    int n = 0;
    const char* p = v;
    while (*p && n < max_len) {
        while (*p == ' ' || *p == '\t') {
            p++;
        }
        if (!*p) {
            break;
        }
        if (p[0] == '?' && p[1] == '?') {
            out_bytes[n] = 0x00;
            out_mask[n] = 0;  // 0 = wildcard
            n++;
            p += 2;
            continue;
        }
        char hex[3] = { p[0], p[1], 0 };
        if (!hex[0] || !hex[1]) {
            break;
        }
        out_bytes[n] = (unsigned char)strtoul(hex, 0, 16);
        out_mask[n] = 1;  // 1 = exact match
        n++;
        p += 2;
    }
    if (out_len) {
        *out_len = n;
    }
    return n > 0;
}

// ---------------------------------------------------------------- manifest gate

ManifestCheck Manifest::validate(const char* prefix) const {
    ManifestCheck result = { 0, 0, 0, 0 };
    HMODULE exe = GetModuleHandleA(NULL);
    if (!exe) {
        return result;
    }
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (keys_[i][0] != 's' || strncmp(keys_[i], "sig.", 4) != 0) {
            continue;
        }
        const char* addrKey = keys_[i] + 4;
        if (prefix && strncmp(addrKey, prefix, strlen(prefix)) != 0) {
            continue;
        }
        const char* addrText = get(addrKey, 0);
        if (!addrText || !*addrText) {
            continue;
        }
        unsigned int va = (unsigned int)strtoul(addrText, 0, 0);
        unsigned char wantBytes[64];
        unsigned char wantMask[64];
        int wantLen = 0;
        if (!getPattern(keys_[i], wantBytes, wantMask, &wantLen, sizeof(wantBytes)) || wantLen == 0) {
            continue;
        }
        result.total++;

        // Live buffer sized safely to 64 bytes (preventing stack buffer overflow)
        unsigned char live[64];
        bool readable = false;
        __try {
            memcpy(live, (void*)va, (size_t)wantLen);
            readable = true;
        }
        __except (EXCEPTION_EXECUTE_HANDLER) {
            readable = false;
        }
        if (!readable) {
            result.unmapped++;
            log().write("WARN", "manifest: %s at 0x%08X is not readable", addrKey, va);
            continue;
        }
        bool ok = true;
        for (int b = 0; b < wantLen; b++) {
            if (wantMask[b] == 0) {
                continue; // wildcard
            }
            if (live[b] != wantBytes[b]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            result.matched++;
        } else {
            result.mismatched++;
            char wantHex[192] = "";
            char liveHex[192] = "";
            for (int b = 0; b < wantLen && b < 16; b++) {
                char h[8];
                if (wantMask[b] == 0) {
                    snprintf(h, sizeof(h), "?? ");
                } else {
                    snprintf(h, sizeof(h), "%02X ", wantBytes[b]);
                }
                strncat(wantHex, h, sizeof(wantHex) - strlen(wantHex) - 1);
                snprintf(h, sizeof(h), "%02X ", live[b]);
                strncat(liveHex, h, sizeof(liveHex) - strlen(liveHex) - 1);
            }
            log().write("WARN", "manifest: %s at 0x%08X does not match this build (expected %s, found %s)",
                        addrKey, va, wantHex, liveHex);
        }
    }
    return result;
}

// ---------------------------------------------------------------- hook registry

bool HookRegistry::install(const char* id, void* target, void* detour, const char* signature, void** origOut) {
    if (!target || !detour) {
        log().write("WARN", "hook '%s' skipped: null target or detour", id);
        return false;
    }
    // Check if already installed at this target
    for (int i = 0; i < count_; i++) {
        if (installed_[i].target == target) {
            log().write("INFO", "hook '%s' already installed at 0x%p", id, target);
            return true;
        }
    }

    // Validate the target memory is readable and looks like code before touching it
    unsigned char p[64];
    bool readable = false;
    __try {
        memcpy(p, target, 8);
        readable = true;
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        readable = false;
    }
    if (!readable || p[0] == 0xCC || p[0] == 0x00) {
        log().write("WARN", "hook '%s' skipped: target 0x%p is not code (first byte 0x%02X, readable: %d)",
                    id, target, readable ? p[0] : 0, readable ? 1 : 0);
        return false;
    }

    // Verify signature BEFORE creating or enabling hook
    if (signature && *signature) {
        const char* sigKey = signature;
        char prefixed[128] = "";
        if (!manifest().get(sigKey, 0) && strncmp(sigKey, "sig.", 4) != 0) {
            snprintf(prefixed, sizeof(prefixed), "sig.%s", sigKey);
            sigKey = prefixed;
        }
        unsigned char wantBytes[64];
        unsigned char wantMask[64];
        int wantLen = 0;
        if (manifest().getPattern(sigKey, wantBytes, wantMask, &wantLen, sizeof(wantBytes)) && wantLen > 0) {
            __try {
                memcpy(p, target, (size_t)wantLen);
            }
            __except (EXCEPTION_EXECUTE_HANDLER) {
                log().write("WARN", "hook '%s' skipped: memory fault reading target 0x%p", id, target);
                return false;
            }
            bool match = true;
            for (int i = 0; i < wantLen; i++) {
                if (wantMask[i] && p[i] != wantBytes[i]) {
                    match = false;
                    break;
                }
            }
            if (!match) {
                log().write("WARN", "hook '%s' skipped: signature mismatch at 0x%p", id, target);
                return false;
            }
        }
    }

#ifndef REMASTER_NO_MINHOOK
    if (origOut) {
        MH_STATUS cs = MH_CreateHook(target, detour, (LPVOID*)origOut);
        if (cs != MH_OK && cs != MH_ERROR_ALREADY_CREATED) {
            log().write("WARN", "hook '%s' MH_CreateHook failed (status %d) at 0x%p", id, cs, target);
            return false;
        }
        MH_STATUS es = MH_EnableHook(target);
        if (es != MH_OK) {
            log().write("WARN", "hook '%s' MH_EnableHook failed (status %d) at 0x%p - removing", id, es, target);
            MH_RemoveHook(target);
            return false;
        }
    }
#endif

    log().write("INFO", "hook '%s' -> 0x%p (prologue %02X %02X %02X %02X %02X)",
                id, target, p[0], p[1], p[2], p[3], p[4]);
    if (count_ < MAX_HOOKS) {
        installed_[count_].id = id;
        installed_[count_].target = target;
        installed_[count_].detour = detour;
        count_++;
    }
    return true;
}

bool HookRegistry::uninstall(const char* id) {
#ifndef REMASTER_NO_MINHOOK
    for (int i = 0; i < count_; i++) {
        if (strcmp(installed_[i].id, id) == 0) {
            MH_DisableHook(installed_[i].target);
            MH_RemoveHook(installed_[i].target);
            log().write("INFO", "hook '%s' uninstalled from 0x%p", id, installed_[i].target);
            installed_[i] = installed_[count_ - 1];
            count_--;
            return true;
        }
    }
#endif
    return false;
}

void HookRegistry::uninstallAll() {
#ifndef REMASTER_NO_MINHOOK
    for (int i = count_ - 1; i >= 0; i--) {
        MH_DisableHook(installed_[i].target);
        MH_RemoveHook(installed_[i].target);
    }
    log().write("INFO", "all %d hooks uninstalled", count_);
#endif
    count_ = 0;
}

void HookRegistry::report() {
    log().write("INFO", "hooks installed: %d", count_);
    for (int i = 0; i < count_; i++) {
        log().write("INFO", "  [%d] %-28s target=0x%p detour=0x%p",
                    i, installed_[i].id, installed_[i].target, installed_[i].detour);
    }
}

HookRegistry& hooks() {
    static HookRegistry r;
    return r;
}

bool moduleDir(char* out, int out_len) {
    DWORD n = GetModuleFileNameA(NULL, out, (DWORD)out_len);
    if (n == 0 || n >= (DWORD)out_len) {
        return false;
    }
    char* slash = strrchr(out, '\\');
    if (slash) {
        slash[1] = 0;
    }
    return true;
}

char* gamePath(const char* leaf) {
    static char buf[MAX_PATH * 2];
    char dir[MAX_PATH];
    if (!moduleDir(dir, sizeof(dir))) {
        return 0;
    }
    _snprintf(buf, sizeof(buf) - 1, "%s%s", dir, leaf);
    buf[sizeof(buf) - 1] = 0;
    return buf;
}

}  // namespace remaster
